// class
function SddpDevice(model, addr, mac)
{
  // Device Config
  this.host = "sony-tv-" + mac;
  this.productName = "sony:tv:" + model;
  this.primaryProxy = "tv";
  this.proxies = "tv";
  this.manufacturer = "Sony";
  this.model = model;
  this.driver = "tv_ip_sony_" + model + ".c4i";
  this.maxAge = 1800; // sec
  this.localOnly = false;
  this.macAddress = mac;
  this.address = addr; // ipv4 only

  // State
  this.searchResponse = false;
  this.tran = "";
  this.notificationType = SddpDevice.NotificationType.NONE;
  this.timePrev = 0; // msec
  this.aliveInterval = 0; // msec
}

// static const
SddpDevice.NotificationType = {NONE:0, ALIVE:1, OFFLINE:2, IDENTIFY:3};

// Prototype
SddpDevice.prototype = {
  getHost : function() {
    return this.host;
  },
  getProductName : function() {
    return this.productName;
  },
  getPrimaryProxy : function() {
    return this.primaryProxy;
  },
  getProxies : function() {
    return this.proxies;
  },
  getManufacturer : function() {
    return this.manufacturer;
  },
  getModel : function() {
    return this.model;
  },
  getDriver : function() {
    return this.driver;
  },
  getMaxAge : function() {
    return this.maxAge;
  },
  isLocalOnly : function() {
    return this.localOnly;
  },
  getMacAddress : function(){
    return this.macAddress;
  },
  getAddress : function(){
    return this.address;
  },
  isSearchResponse : function() {
    return this.searchResponse;
  },
  getTran : function() {
    return this.tran;
  },
  getNotificationType : function() {
    return this.notificationType;
  },
  getTimePrev : function() {
    return this.timePrev;
  },
  getAliveInterval : function() {
    return this.aliveInterval;
  },
  setHost : function(argHost) {
    if (typeof argHost == "string") {
      this.host = argHost;
    }
  },
  setProductName : function(argProductName) {
    if (typeof argProductName == "string") {
      this.productName = argProductName;
    }
  },
  setPrimaryProxy : function(argPrimaryProxy) {
    if (typeof argPrimaryProxy == "string") {
      this.primaryProxy = argPrimaryProxy;
    }
  },
  setProxies : function(argProxies) {
    if (typeof argProxies == "string") {
      this.proxies = argProxies;
    }
  },
  setManufacturer : function(argManufacturer) {
    if (typeof argManufacturer == "string") {
      this.manufacturer = argManufacturer;
    }
  },
  setDriver : function(argDriver) {
    if (typeof argDriver == "string") {
      this.driver = argDriver;
    }
  },
  setMaxAge : function(argMaxAge) {
    if (typeof argMaxAge == "number") {
      this.maxAge = argMaxAge;
    }
  },
  setLocalOnly : function(argLocalOnly) {
    if (typeof argLocalOnly == "boolean") {
      this.localOnly = argLocalOnly;
    }
  },
  setSearchResponse : function(argSearchResponse) {
    if (typeof argSearchResponse == "boolean") {
      this.searchResponse = argSearchResponse;
    }
  },
  setTran : function(argTran) {
    if (typeof argTran == "string") {
      this.tran = argTran;
    }
  },
  setNotificationType : function(argNotificationType) {
    if (typeof argNotificationType == "number") {
      this.notificationType = argNotificationType;
    }
  },
  setTimePrev : function(argTimePrev) {
    if (typeof argTimePrev == "number") {
      this.timePrev = argTimePrev;
    }
  },
  setAliveInterval : function(argAliveInterval) {
    if (typeof argAliveInterval == "number") {
      this.aliveInterval = argAliveInterval;
    }
  }
};

exports.SddpDevice = SddpDevice;
exports.createSddpDevice = function(model, addr, mac) {
    return new SddpDevice(model, addr, mac);
};
